<script setup lang="ts">
import{ref,watch,onBeforeUnmount}from'vue';import{requestClient}from'#/api/request';const props=defineProps<{src:string}>();const url=ref(''),error=ref(''),video=ref<HTMLVideoElement>();let turn=0;
async function load(){const mine=++turn;url.value='';error.value='';if(!props.src)return;try{const match=props.src.match(/^\/api\/media\/(\d+)\/content/);const value=match?(await requestClient.get<{url:string}>(`/media/${match[1]}/playback`)).url:props.src;if(mine===turn)url.value=value}catch{if(mine===turn)error.value='视频暂时无法读取，请重试。'}}watch(()=>props.src,load,{immediate:true});onBeforeUnmount(()=>{turn++;video.value?.pause()});
</script><template><div class="video-preview"><video v-if="url&&!error" ref="video" :src="url" controls playsinline preload="metadata" @error="error='无法播放此视频，请重试或确认编码。'"/><div v-if="error" role="alert">{{error}}<button @click="load">重新加载</button></div></div></template><style scoped>.video-preview video{width:100%;max-height:420px;border-radius:14px;background:var(--el-bg-color-page)}.video-preview button{display:block;padding:10px;color:var(--el-color-primary)}.video-preview{max-width:720px}</style>
